begin;
select set_config('request.jwt.claim.sub','91c5b7f0-7018-4290-a190-c2bba0ca492d',true);
select set_config('request.jwt.claims','{"sub":"91c5b7f0-7018-4290-a190-c2bba0ca492d","role":"authenticated"}',true);
do $$declare uid uuid:=auth.uid();sid uuid;rid uuid;drop_id uuid;n integer;failed boolean;r jsonb;begin
 select session_id into sid from eldervale_private.realm_players where user_id=uid;
 update eldervale_private.realm_players set x=-340,z=-282,last_seen=clock_timestamp(),last_command=clock_timestamp()-interval '1 second',input_until=null,input_x=0,input_z=0,path='[]',intent=null where user_id=uid;
 update eldervale_private.realm_actors set target=null where target=uid;
 update public.player_saves set stats='{}',inventory='{"bank":{"weapon:longsword":100,"wood":100,"bait":10000},"armorOwned":[],"weaponsOwned":[],"shieldsOwned":[],"jewelryOwned":[],"mountsOwned":[]}',equipment='{}' where user_id=uid;
 insert into eldervale_private.realm_objects(id,kind,x,z,data) values('test:notes:bank','door',-339,-282,'{"type":"bank"}');
 rid:=gen_random_uuid();perform eldervale_private.realm_request(sid,'bank','{"item":"weapon:longsword","direction":"withdraw","all":true}',rid,0);perform eldervale_private.realm_request(sid,'bank','{"item":"weapon:longsword","direction":"withdraw","all":true}',rid,0);
 if eldervale_private.item_quantity(uid,'weapon:longsword')<>16 or eldervale_private.inventory_used(uid)<>16 or (select (inventory->'bank'->>'weapon:longsword')::integer from public.player_saves where user_id=uid)<>84 then raise exception 'Physical equipment slots or request idempotency failed';end if;
 update eldervale_private.realm_players set last_command=clock_timestamp()-interval '1 second' where user_id=uid;
 perform eldervale_private.realm_request(sid,'equip','{"slot":"weapon","key":"longsword"}',gen_random_uuid(),0);if eldervale_private.inventory_used(uid)<>15 then raise exception 'Wielding must reserve exactly one copy';end if;
 perform eldervale_private.realm_request(sid,'bank','{"item":"weapon:longsword","direction":"deposit","all":true}',gen_random_uuid(),0);if eldervale_private.item_quantity(uid,'weapon:longsword')<>1 or eldervale_private.inventory_used(uid)<>0 then raise exception 'Deposit removed wielded weapon';end if;
 perform eldervale_private.realm_request(sid,'bank','{"item":"weapon:longsword","direction":"withdraw","all":true,"noted":true}',gen_random_uuid(),0);
 if eldervale_private.item_quantity(uid,'note:weapon:longsword')<>99 or eldervale_private.item_quantity(uid,'weapon:longsword')<>1 or eldervale_private.inventory_used(uid)<>1 then raise exception 'Noted withdrawal failed conservation';end if;
 failed:=false;begin update eldervale_private.realm_players set last_command=clock_timestamp()-interval '1 second' where user_id=uid;perform eldervale_private.realm_request(sid,'equip','{"slot":"weapon","key":"note:longsword"}',gen_random_uuid(),0);exception when others then failed:=true;end;if not failed then raise exception 'Noted sword was equippable';end if;
 perform eldervale_private.realm_request(sid,'bank','{"item":"note:weapon:longsword","direction":"deposit","all":true}',gen_random_uuid(),0);
 perform eldervale_private.realm_request(sid,'bank','{"item":"weapon:longsword","direction":"withdraw","all":true,"noted":false}',gen_random_uuid(),0);
 if eldervale_private.item_quantity(uid,'weapon:longsword')<>17 or (select (inventory->'bank'->>'weapon:longsword')::integer from public.player_saves where user_id=uid)<>83 then raise exception 'Unnoted copies or bank balance incorrect';end if;
 perform eldervale_private.realm_request(sid,'bank','{"item":"weapon:longsword","direction":"deposit","all":true}',gen_random_uuid(),0);
 perform eldervale_private.realm_request(sid,'bank','{"item":"wood","direction":"withdraw","all":true,"noted":true}',gen_random_uuid(),0);
 perform eldervale_private.realm_request(sid,'bank','{"item":"bait","direction":"withdraw","all":true,"noted":true}',gen_random_uuid(),0);
 if eldervale_private.item_quantity(uid,'bait')<>10000 or eldervale_private.item_quantity(uid,'note:wood')<>100 or exists(select 1 from eldervale_private.realm_catalog where id='item:note:bait') then raise exception 'Naturally stackable items were incorrectly noted';end if;
 perform eldervale_private.item_change(uid,'matches',1);select data into r from eldervale_private.skill_recipes where id='burn_wood';if eldervale_private.skill_error(uid,r,null) not like '%enough wood%' then raise exception 'Notes substituted for real logs';end if;
 r:=jsonb_build_object('inputs','{"note:wood":1}'::jsonb,'tools','[]'::jsonb);if eldervale_private.skill_error(uid,r,null) not like '%Bank notes%' then raise exception 'Noted recipe input accepted';end if;
 perform eldervale_private.validate_offer(uid,'{"items":{"note:wood":40},"gold":0}');
 update eldervale_private.realm_players set last_command=clock_timestamp()-interval '1 second' where user_id=uid;
 perform eldervale_private.realm_request(sid,'drop','{"item":"note:wood","amount":40}',gen_random_uuid(),0);
 select id into drop_id from eldervale_private.ground_drops where owner_id=uid and item='note:wood' order by created_at desc limit 1;
 if drop_id is null or eldervale_private.item_quantity(uid,'note:wood')<>60 then raise exception 'Noted drop failed';end if;
 update eldervale_private.realm_players set last_command=clock_timestamp()-interval '1 second' where user_id=uid;
 perform eldervale_private.realm_request(sid,'pickup_drop',jsonb_build_object('id',drop_id),gen_random_uuid(),0);if eldervale_private.item_quantity(uid,'note:wood')<>100 then raise exception 'Note pickup changed its form or quantity';end if;
 update eldervale_private.realm_players set x=-240,z=-280 where user_id=uid;failed:=false;begin perform eldervale_private.realm_request(sid,'bank','{"item":"note:wood","direction":"deposit","all":true}',gen_random_uuid(),0);exception when others then failed:=true;end;if not failed then raise exception 'Notes were exchangeable away from a bank';end if;
end $$;
select 'PASS: physical sword copies, stacked notes, bank-only conversion, wielded-copy protection, replay safety, bait stacking, skill restrictions, trade offer validation, drops and pickup' as result;
